// src/client/styles/index.js
var CSS = [baseStyles, captureStyles, wallStyles, readerStyles, settingsStyles, overridesStyles].join("\n");
function injectStyles() {
  if (typeof document === "undefined" || !document.head) return void 0;
  const stale = document.querySelector('style[data-plugin="sticky-notes"]');
  if (stale && stale.parentNode) stale.parentNode.removeChild(stale);
  const tag = document.createElement("style");
  tag.dataset.plugin = "sticky-notes";
  tag.dataset.pluginCss = "dsh-obsidian-memo/client.css";
  tag.textContent = CSS;
  document.head.appendChild(tag);
  return () => {
    if (tag.parentNode) tag.parentNode.removeChild(tag);
  };
}

